            '__recovery_secure_desc__' => __('Signs everyone out of this site, on every device, and revokes every application password. Nothing is deleted and nobody is emailed: anyone who should be here simply signs in again. You stay signed in.', 'fluent-security'),
            '__reinstall_extension_desc__' => __('Downloads this version from WordPress.org and replaces the whole folder, so a changed file you cannot see is put back along with the ones you can. Settings are kept. Anything here that is not part of the official copy is moved to quarantine first.', 'fluent-security'),
            '__relay_disabled_desc__' => __('This site was switched off on your alerts dashboard, so scan reports are no longer being accepted and no alerts will be sent. Re-enable it there, then resume reporting here.', 'fluent-security'),
